int checks=0;void Check(bool b,string why){checks++;if(!b)throw new Exception($"check {checks}: {why}");}
void Reject(Action a,string why){bool rejected=false;try{a();}catch(InvalidOperationException){rejected=true;}Check(rejected,why);}
GameItem Item(string id,int x,int y,int w=1,int h=1,bool window=false,int o=0,string cat="MISC")=>new(){identifier=id,Name=id,uniqueId=1,modifiedShape=GridShape.Rect(w,h,x,y,o),itemTypes=new(){cat},contentWindow=window?new PixelWindow():null};
string Pose(GameItem i)=>$"{i.modifiedShape.minX},{i.modifiedShape.minY},{i.modifiedShape.orientation}:{string.Join(';',i.modifiedShape.Cells)}";
string State(GameGridInventory inv)=>string.Join('|',inv.childItems.Select(i=>$"{i.Pointer}:{i.identifier}:{i.uniqueId}:{i.unitCount}:{i.state}:{Pose(i)}"));
LayoutResult Solve(InventoryTransaction tx){using var c=new GlobalArrangeController();var r=c.Begin(tx.Problem,tx.OriginalPlacements,tx.SessionContext);return tx.OrderInstances(r.Session.Advance(r.NodeBudget,r.SolutionBatch).Result);}
void Complete(InventoryTransaction tx,LayoutResult r){Check(r.Complete,"complete");Check(Native34Solver.ValidateLayout(tx.Problem,r.Placements),"legal geometry");Check(r.Placements.Count==tx.MovableCount,"all movable");Check(r.Placements.Select(p=>p.StableId).Distinct().Count()==tx.MovableCount,"no duplicate IDs");}
new SmartArrangeMod().OnInitializeMelon();Check(SmartArrangeMod.KeepContainers.Value,"config default true");Check(MelonPreferences.Keys.SequenceEqual(new[]{"SmartInventoryArrange/KeepContainers"}),"own preference only");
foreach(string cat in new[]{"SHELF","CAGE","BACKPACK","CONTAINER","MACHINE","MISC"})
foreach(bool has in new[]{false,true})foreach(bool visible in new[]{false,true})foreach(int count in new[]{0,2}){
 var inv=new GameGridInventory();var item=Item(cat,4,2,2,2,has,cat:cat);if(has){item.contentWindow!.Visible=visible;item.contentWindow.ContentCount=count;}inv.Add(item);
 var keep=InventoryTransaction.Capture(inv,true);Check(keep.FixedCount==(has?1:0),"window-only fixed predicate "+cat);Check(keep.MovableCount==(has?0:1),"movable classification");Check(keep.PreservedContainerCount==(has?1:0),"fixed diagnostics");
 int reads=GameItem.WindowReads;var normal=InventoryTransaction.Capture(inv);Check(GameItem.WindowReads==reads,"normal never reads contentWindow");Check(normal.FixedCount==0&&normal.MovableCount==1,"normal unchanged");
 if(has){item.contentWindow!.Visible=!visible;keep.AssertSnapshotCurrent();Check(true,"visibility irrelevant");}
}
{var inv=new GameGridInventory();var item=Item("locked",3,2,2,2,true);item.Removable=false;inv.Add(item);foreach(bool keep in new[]{false,true}){var tx=InventoryTransaction.Capture(inv,keep);Check(tx.FixedCount==1&&tx.MovableCount==0&&tx.PreservedContainerCount==0,"native lock preserved");}}
