 var tx=InventoryTransaction.Capture(inv,true);string pa=Pose(a),pb=Pose(b),state=State(inv);var r=Solve(tx);Complete(tx,r);Check(!r.UsedFallback,"fresh result");var again=Solve(InventoryTransaction.Capture(inv,true));Check(Native34Solver.SameLayout(r.Placements,again.Placements),"deterministic");tx.AssertSnapshotCurrent();tx.Apply(r.Placements);
 Check(Pose(a)==pa&&Pose(b)==pb,"fixed coordinates+direction unchanged");Check(!inv.LastIgnored.Contains(a)&&!inv.LastIgnored.Contains(b),"fixed not ignored by native collisions");Check(inv.childItems.Count==6&&inv.childItems.All(i=>i.unitCount==1&&i.state.dict.Count==0),"count and state conserved");Check(inv.childItems.Select(i=>i.Pointer).Distinct().Count()==6,"instances unique");tx.RestoreCapturedSnapshot();Check(State(inv)==state,"full rollback exact");scenarios.Add(new{width=size.Item1,height=size.Item2,complete=true,fixedCount=tx.FixedCount,rollbackExact=true});
}
{var inv=new GameGridInventory(6,6);var a=Item("cage",0,0,2,2,true);a.modifiedShape.DefaultCells=new[]{(0,0),(1,0),(0,1)};inv.Add(a);inv.inventoryShape.Disabled.Add((5,5));inv.Add(Item("small",4,4));var tx=InventoryTransaction.Capture(inv,true);var r=Solve(tx);Complete(tx,r);Check(tx.Problem.Fixed.Single().Mask.Area==3,"irregular mask");tx.Apply(r.Placements);Check(Pose(a).StartsWith("0,0,0:"),"irregular fixed unchanged");}
{var inv=new GameGridInventory(24,10);var a=Item("sec_box",2,2,6,4,true,1,"SUPPLY_CRATE");var b=Item("sec_box",12,2,6,4,false,1,"SUPPLY_CRATE");b.uniqueId=2;inv.Add(a);inv.Add(b);var tx=InventoryTransaction.Capture(inv,true);Check(tx.Problem.Fixed.Single().GameOrientation==1,"fixed crate actual vertical");Check(tx.Problem.Items.Single().Orientations.All(o=>o.GameOrientation==0),"movable crate horizontal rule retained");var r=Solve(tx);Complete(tx,r);tx.Apply(r.Placements);Check(a.modifiedShape.orientation==1&&a.modifiedShape.minX==2&&a.modifiedShape.minY==2,"fixed crate exact pose");Check(b.modifiedShape.orientation==0,"movable crate horizontal");}
