{var inv=new GameGridInventory();inv.Add(Item("box",3,2,2,2,true));inv.Add(Item("small",1,1));var n=InventoryTransaction.Capture(inv);var k=InventoryTransaction.Capture(inv,true);using var c=new GlobalArrangeController();var r=c.Begin(n.Problem,n.OriginalPlacements,n.SessionContext);Check(r.Restarted,"first fresh");c.Complete(r,n.Problem,n.OriginalPlacements);r=c.Begin(k.Problem,k.OriginalPlacements,k.SessionContext);Check(r.Restarted,"mode change resets frontier");c.Complete(r,k.Problem,k.OriginalPlacements);Check(!c.Begin(k.Problem,k.OriginalPlacements,k.SessionContext).Restarted,"same mode resumes");}
foreach(bool corrupt in new[]{false,true}){var inv=new GameGridInventory();var a=Item("machine",4,2,2,2,true);inv.Add(a);inv.Add(Item("small",7,6));var tx=InventoryTransaction.Capture(inv,true);string before=State(inv);var r=Solve(tx);Complete(tx,r);if(corrupt)inv.OnValidate=()=>a.modifiedShape=GridShape.Rect(2,2,9,5);else inv.RejectSlot=true;Reject(()=>tx.Apply(r.Placements),corrupt?"post-apply fixed pose guard":"native slot rejection");Check(State(inv)==before,"all poses restored on apply failure");}
